model:
rachana: 1
sutra: counterparty-group
version: 2
description: 
match: { kind: counterparty-group, priority: 10 }
title: { pill: "Counterparty and legal · Counterparty group", id: "$.GROUP_ID" }
strip:
  - { label: "Name", bind: "$.NAME" }
  - { label: "Members", bind: "size($.MEMBERS)" }
  - { label: "Group limit", bind: "$.LIMIT", fmt: "compact" }
  - { label: "Utilisation", bind: "$.UTILISATION", fmt: "pct0", emphasis: true }
panels:
  - id: members
    kind: table
    title: "Members"
    key: "F2"
    rows: "$.MEMBERS"
    columns:
      - { label: "Counterparty", bind: "@.ID", link: true }
      - { label: "Name", bind: "@.NAME" }
      - { label: "Rating", bind: "@.RATING" }
  - id: built
    kind: provenance
    title: "How this view was built"
keys: { F8: "impact", F9: "raw" }
